import {isIncapacitated} from './status.js';
import {CHARACTERS} from '../characters/index.js';
import {MADARA_ULTIMATE_CINEMATIC_STEPS,NARUTO_V2_KCM_STEPS,NARUTO_V2_BARYON_STEPS,RENGOKU_ULTIMATE_CINEMATIC_STEPS} from './ultimate-rules.js';
import {SUKUNA_ULTIMATE_CINEMATIC_STEPS,GOJO_ULTIMATE_CINEMATIC_STEPS,TATSUMAKI_ULTIMATE_CINEMATIC_STEPS,BOA_ULTIMATE_CINEMATIC_STEPS,SABER_ULTIMATE_CINEMATIC_STEPS,ULTIMATE_CINEMATIC_STEPS,ULTIMATE_DAMAGE_MULTIPLIER,ULTRA_ULTIMATE_CINEMATIC_STEPS,ICHIGO_ULTIMATE_CINEMATIC_STEPS,cinematicSteps} from './ultimate-rules.js';
export const PERSONAL_ULTIMATE_IDS=['madara','naruto_v2','rengoku','sukuna','gojo','ichigo','sung_jinwoo','goku_ultra','saber','tatsumaki','boa_hancock'];
export function personalRageMultiplier(f){return CHARACTERS[f.id]?.rageGainMultiplier?.(f)??1;}
export function recordPersonalDamage(d,source,target,amount,ultimate=false){
 if(ultimate||amount<=0||!d.isEnemy(source,target))return;
 for(const [f,gain] of [[source,150*amount/target.max],[target,80*amount/target.max]])if(PERSONAL_ULTIMATE_IDS.includes(f.id)&&d.tick>=f.rageLockUntil){f.rage=Math.min(100,f.rage+gain*personalRageMultiplier(f));if(f.rage>=100&&f.rageReadyTick===null)f.rageReadyTick=d.tick;}
}
export function personalCaster(d,f){const u=d.personalUltimate,a=u?.cinematic||u?.attack;return a?.ownerUid===f.uid&&(u.cinematic||a.phase==='warning'||(a.kind==='supreme'&&!a.beamFired)||(a.kind==='meteor'&&d.tick<a.impactTick)||(a.kind==='judgment'&&d.tick<a.launch+48)||(['purgatory','finalimpact'].includes(a.kind)&&d.tick<a.launch+36))?a:null;}
export function personalDanger(d,f){const a=d.personalUltimate?.attack;if(!a||a.phase!=='warning')return false;const owner=d.fighters.find(f=>f.uid===a.ownerUid);if(!owner||!d.isEnemy(owner,f))return false;if(['purgatory','finalimpact'].includes(a.kind)){const x=f.x-a.x,y=f.y-a.y,along=x*a.dx+y*a.dy;return along>0&&along<666&&Math.abs(x*a.dy-y*a.dx)<100;}if(a.kind==='meteor')return Math.hypot(f.x-a.targetX,f.y-a.targetY)<220;if(a.kind==='shrine')return Math.hypot(f.x-a.x,f.y-a.y)<200;if(a.kind==='void')return Math.hypot(f.x-a.targetX,f.y-a.targetY)<190;if(a.kind==='kuramarasengan')return Math.hypot(f.x-a.targetX,f.y-a.targetY)<175;if(a.kind==='cataclysm')return Math.hypot(f.x-a.targetX,f.y-a.targetY)<185;const dx=f.x-a.x,dy=f.y-a.y;return dx*a.dx+dy*a.dy>0&&Math.abs(dx*a.dy-dy*a.dx)<100;}
export function stepPersonalUltimate(d){
 const u=d.personalUltimate;if(!u)return false;
 if(!u.cinematic&&!u.attack&&!d.teamUltimate?.cinematic&&!d.teamUltimate?.attack){const f=d.fighters.filter(f=>PERSONAL_ULTIMATE_IDS.includes(f.id)&&f.hp>0&&f.rage>=100&&d.tick>=f.rageLockUntil&&!isIncapacitated(d,f)).sort((a,b)=>(a.rageReadyTick??d.tick)-(b.rageReadyTick??d.tick))[0],t=f&&d.pickTarget(f);if(t){const dx=t.x-f.x,dy=t.y-f.y,n=Math.hypot(dx,dy)||1;u.cinematic={kind:f.id==='madara'?'meteor':f.id==='naruto_v2'?(f.baryon?'finalimpact':'kuramarasengan'):f.id==='rengoku'?'purgatory':f.id==='sukuna'?'shrine':f.id==='gojo'?'void':f.id==='boa_hancock'?'judgment':f.id==='tatsumaki'?'cataclysm':f.id==='saber'?'excalibur':f.id==='goku_ultra'?'supreme':f.id==='sung_jinwoo'?'arise':'fullgetsuga',ownerUid:f.uid,durationSteps:f.id==='madara'?MADARA_ULTIMATE_CINEMATIC_STEPS:f.id==='naruto_v2'?(f.baryon?NARUTO_V2_BARYON_STEPS:NARUTO_V2_KCM_STEPS):f.id==='rengoku'?RENGOKU_ULTIMATE_CINEMATIC_STEPS:f.id==='sukuna'?SUKUNA_ULTIMATE_CINEMATIC_STEPS:f.id==='gojo'?GOJO_ULTIMATE_CINEMATIC_STEPS:f.id==='tatsumaki'?TATSUMAKI_ULTIMATE_CINEMATIC_STEPS:f.id==='boa_hancock'?BOA_ULTIMATE_CINEMATIC_STEPS:f.id==='saber'?SABER_ULTIMATE_CINEMATIC_STEPS:f.id==='goku_ultra'?ULTRA_ULTIMATE_CINEMATIC_STEPS:f.id==='ichigo'?ICHIGO_ULTIMATE_CINEMATIC_STEPS:ULTIMATE_CINEMATIC_STEPS,elapsed:0,x:f.x,y:f.y,targetX:t.x,targetY:t.y,targetUid:t.uid,dx:dx/n,dy:dy/n};f.rage=0;f.rageReadyTick=null;f.rageLockUntil=0;f.personalUses++;f.state='idle';f.age=0;f.face=Math.sign(dx)||f.face;d.event('personalStart',f);}}
 if(!u.cinematic)return false;u.cinematic.elapsed++;if(u.cinematic.elapsed>=cinematicSteps(u.cinematic)){u.attack={...u.cinematic,phase:'warning',born:d.tick,launch:d.tick+36};u.cinematic=null;}return true;
}
export function tickPersonalUltimate(d,hits=[]){const u=d.personalUltimate,a=u?.attack;if(!a)return;const f=d.fighters.find(f=>f.uid===a.ownerUid);if(a.phase==='warning'&&(!f||f.hp<=0||isIncapacitated(d,f))){u.attack=null;return;}if(a.phase==='warning'&&d.tick>=a.launch){a.phase='travel';if(a.kind==='meteor'){a.impactTick=d.tick+42;}else if(a.kind==='arise'){a.hitKeys=[];}else if(a.kind==='supreme'){const t=d.pickTarget(f);if(d.tick>=(f.rootUntil||0)){const move=Math.min(180,Math.max(0,Math.hypot((t?.x??f.x)-f.x,(t?.y??f.y)-f.y)-75));f.x+=a.dx*move;f.y+=a.dy*move;d.clampPosition(f);}a.x=f.x;a.y=f.y;a.beamTick=d.tick+12;for(const t of d.fighters)if(t.hp>0&&d.isEnemy(f,t)&&Math.hypot(t.x-f.x,t.y-f.y)<120)hits.push({source:f,target:t,value:100*ULTIMATE_DAMAGE_MULTIPLIER,ultimate:true,knockback:30});d.event('ultraStrike',f,{x:f.x+a.dx*60,y:f.y+a.dy*60});}else if(a.kind==='judgment'){a.waves=0;}else if(a.kind==='void'||a.kind==='shrine'){a.pulses=0;}else if(['cataclysm','kuramarasengan'].includes(a.kind)){a.impactTick=d.tick+30;}else if(['purgatory','finalimpact'].includes(a.kind)){a.hitUids=[];}else if(a.kind==='excalibur')d.shots.push({id:'saber',ownerUid:f.uid,kind:'excalibur',skill:'excalibur',ultimate:true,damage:420*ULTIMATE_DAMAGE_MULTIPLIER,radius:75,x:a.x+a.dx*45,y:a.y+a.dy*45,vx:a.dx*720,vy:a.dy*720,life:2.4,piercing:true,hitUids:[],impactEvent:'excaliburImpact'});else d.shots.push({id:'ichigo',ownerUid:f.uid,kind:'fullgetsuga',skill:'fullgetsuga',ultimate:true,damage:420*ULTIMATE_DAMAGE_MULTIPLIER,radius:85,x:a.x+a.dx*45,y:a.y+a.dy*45,vx:a.dx*680,vy:a.dy*680,life:2.5,piercing:true,hitUids:[],impactEvent:'ichigoUltimateImpact'});d.event('personalLaunch',f,{x:a.x,y:a.y});}
 if(a.phase==='travel'&&['purgatory','finalimpact'].includes(a.kind)){
  if(!f||f.hp<=0||isIncapacitated(d,f)){u.attack=null;return;}
  if(d.tick-a.launch<36){const fromX=f.x,fromY=f.y;if(d.tick>=(f.rootUntil||0)){f.x+=a.dx*16;f.y+=a.dy*16;d.clampPosition(f);}const mx=f.x-fromX,my=f.y-fromY,len=mx*mx+my*my;
   for(const t of d.fighters){if(t.hp<=0||!d.isEnemy(f,t)||a.hitUids.includes(t.uid))continue;const q=len?Math.max(0,Math.min(1,((t.x-fromX)*mx+(t.y-fromY)*my)/len)):0;
    if(Math.hypot(t.x-fromX-q*mx,t.y-fromY-q*my)<90){a.hitUids.push(t.uid);hits.push({source:f,target:t,value:420*ULTIMATE_DAMAGE_MULTIPLIER,ultimate:true,knockback:45});d.event(a.kind==='finalimpact'?'v2UltimateImpact':'rengokuUltimateImpact',f,{x:t.x,y:t.y,form:'baryon'});}}}
  if(d.tick>=a.launch+72){u.attack=null;return;}
 }
 if(a.phase==='travel'&&a.kind==='shrine'){if(!f||f.hp<=0||isIncapacitated(d,f)){u.attack=null;return;}while(a.pulses<6&&d.tick>=a.launch+a.pulses*30){a.pulses++;for(const t of d.fighters)if(t.hp>0&&d.isEnemy(f,t)&&Math.hypot(t.x-a.x,t.y-a.y)<200)hits.push({source:f,target:t,value:70*ULTIMATE_DAMAGE_MULTIPLIER,ultimate:true});d.event('shrinePulse',f,{x:a.x,y:a.y});}if(d.tick>=a.launch+180){u.attack=null;return;}}
 if(a.phase==='travel'&&a.kind==='void'){if(!f||f.hp<=0||isIncapacitated(d,f)){u.attack=null;return;}while(a.pulses<5&&d.tick>=a.launch+a.pulses*24){const last=a.pulses++===4;for(const t of d.fighters)if(t.hp>0&&d.isEnemy(f,t)&&Math.hypot(t.x-a.targetX,t.y-a.targetY)<190)hits.push({source:f,target:t,value:(last?100:80)*ULTIMATE_DAMAGE_MULTIPLIER,ultimate:true,rootTicks:last?0:18});d.event('voidPulse',f,{x:a.targetX,y:a.targetY,final:last});}if(d.tick>=a.launch+120)u.attack=null;}
 if(a.phase==='travel'&&a.kind==='judgment'){if((!f||f.hp<=0||isIncapacitated(d,f))&&a.waves<4){u.attack=null;return;}while(a.waves<4&&d.tick>=a.launch+[0,12,24,42][a.waves]){const wave=a.waves++,kick=wave===3;d.shots.push({id:'boa_hancock',ownerUid:f.uid,kind:kick?'judgmentkick':'judgmentarrow',skill:'judgment',ultimate:true,damage:(kick?165:85)*ULTIMATE_DAMAGE_MULTIPLIER,radius:kick?70:60,x:a.x+a.dx*40,y:a.y+a.dy*40,vx:a.dx*(kick?800:700),vy:a.dy*(kick?800:700),life:1.6,piercing:true,hitUids:[],petrifyTicks:wave===0?18:0,impactEvent:'judgmentImpact'});d.event('fire',f,{skill:'judgment'});}if(d.tick>=a.launch+150)u.attack=null;}
 if(a.phase==='travel'&&a.kind==='supreme'&&!a.beamFired&&d.tick>=a.beamTick){if(!f||f.hp<=0||isIncapacitated(d,f)){u.attack=null;return;}a.beamFired=true;d.shots.push({id:'goku_ultra',ownerUid:f.uid,kind:'supreme',skill:'supreme',ultimate:true,damage:340*ULTIMATE_DAMAGE_MULTIPLIER,radius:65,x:a.x+a.dx*45,y:a.y+a.dy*45,vx:a.dx*800,vy:a.dy*800,life:2,piercing:true,hitUids:[],impactEvent:'ultraUltimateImpact'});d.event('fire',f,{skill:'supreme'});}
 if(a.phase==='travel'&&a.kind==='cataclysm'){if(!a.hit&&d.tick>=a.impactTick){a.hit=true;for(const t of d.fighters)if(t.hp>0&&d.isEnemy(f,t)&&Math.hypot(t.x-a.targetX,t.y-a.targetY)<165)hits.push({source:f,target:t,value:420*ULTIMATE_DAMAGE_MULTIPLIER,ultimate:true,knockback:60});d.event('cataclysmImpact',f,{x:a.targetX,y:a.targetY});}if(d.tick>=a.launch+78)u.attack=null;}
 if(a.phase==='travel'&&a.kind==='meteor'){if(!a.hit&&d.tick>=a.impactTick){a.hit=true;for(const t of d.fighters)if(t.hp>0&&d.isEnemy(f,t)&&Math.hypot(t.x-a.targetX,t.y-a.targetY)<200)hits.push({source:f,target:t,value:420*ULTIMATE_DAMAGE_MULTIPLIER,ultimate:true,knockback:60});d.event('madaraMeteorImpact',f,{x:a.targetX,y:a.targetY});}if(d.tick>=a.launch+102)u.attack=null;}
 if(a.phase==='travel'&&a.kind==='kuramarasengan'){if(!a.hit&&d.tick>=a.impactTick){a.hit=true;for(const t of d.fighters)if(t.hp>0&&d.isEnemy(f,t)&&Math.hypot(t.x-a.targetX,t.y-a.targetY)<165)hits.push({source:f,target:t,value:420*ULTIMATE_DAMAGE_MULTIPLIER,ultimate:true,knockback:60});d.event('v2UltimateImpact',f,{x:a.targetX,y:a.targetY,form:'kcm'});}if(d.tick>=a.launch+78)u.attack=null;}
 if(a.phase==='travel'&&a.kind==='arise'){for(let wave=0;wave<3;wave++){const age=d.tick-a.launch-wave*15;if(age<0||age>60)continue;const reach=age*12,previous=Math.max(0,reach-12);for(const t of d.fighters){const key=t.uid+':'+wave;if(t.hp<=0||!d.isEnemy(f,t)||a.hitKeys.includes(key))continue;const tx=t.x-a.x,ty=t.y-a.y,along=tx*a.dx+ty*a.dy,across=Math.abs(tx*a.dy-ty*a.dx);if(along>=previous-65&&along<=reach+65&&across<105){a.hitKeys.push(key);hits.push({source:f,target:t,value:120*ULTIMATE_DAMAGE_MULTIPLIER,ultimate:true});d.event('ariseImpact',f,{x:t.x,y:t.y});}}}if(d.tick>=a.launch+90)u.attack=null;}
 else if(a.phase==='travel'&&a.kind!=='shrine'&&d.tick>=a.launch+160)u.attack=null;
}
